1	package store
2	
3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// State is everything a store holds, for snapshots (package snapshot). Slices are sorted by ID.
9	type State struct {
10		Seq              int               `json:"seq"`
11		Orgs             []Org             `json:"orgs"`
12		Users            []User            `json:"users"`
13		Members          []Member          `json:"members"`
14		APIKeys          []APIKey          `json:"api_keys"`
15		Invites          []Invite          `json:"invites"`
16		Customers        []Customer        `json:"customers"`
17		Plans            []Plan            `json:"plans"`
18		Subscriptions    []Subscription    `json:"subscriptions"`
19		Usage            []UsageRecord     `json:"usage"`
20		Invoices         []Invoice         `json:"invoices"`
21		Payments         []Payment         `json:"payments"`
22		WebhookEndpoints []WebhookEndpoint `json:"webhook_endpoints"`
23		Events           []Event           `json:"events"`
24		Deliveries       []Delivery        `json:"deliveries"`
25	}
26	
27	// Export returns a copy of everything in the store.
28	func (s *Store) Export() State {
29		s.mu.Lock()
30		defer s.mu.Unlock()
31		st := State{Seq: s.seq}
32		for _, o := range s.orgs {
33			st.Orgs = append(st.Orgs, o)
34		}
35		for _, u := range s.users {
36			st.Users = append(st.Users, u)
37		}
38		for _, m := range s.members {
39			st.Members = append(st.Members, m)
40		}
41		for _, k := range s.apiKeys {
42			st.APIKeys = append(st.APIKeys, k)
43		}
44		for _, i := range s.invites {
45			st.Invites = append(st.Invites, i)
46		}
47		for _, c := range s.customers {
48			st.Customers = append(st.Customers, copyCustomer(c))
49		}
50		for _, p := range s.plans {
51			st.Plans = append(st.Plans, p)
52		}
53		for _, sub := range s.subs {
54			st.Subscriptions = append(st.Subscriptions, copySub(sub))
55		}
56		st.Usage = append(st.Usage, s.usage...)
57		for _, inv := range s.invoices {
58			st.Invoices = append(st.Invoices, copyInvoice(inv))
59		}
60		for _, p := range s.payments {
61			st.Payments = append(st.Payments, p)
62		}
63		for _, ep := range s.endpoints {
64			st.WebhookEndpoints = append(st.WebhookEndpoints, copyEndpoint(ep))
65		}
66		for _, e := range s.events {
67			st.Events = append(st.Events, e)
68		}
69		for _, d := range s.delivs {
70			st.Deliveries = append(st.Deliveries, copyDelivery(d))
71		}
72		sort.Slice(st.Orgs, func(i, j int) bool { return st.Orgs[i].ID < st.Orgs[j].ID })
73		sort.Slice(st.Users, func(i, j int) bool { return st.Users[i].ID < st.Users[j].ID })
74		sort.Slice(st.Members, func(i, j int) bool {
75			if st.Members[i].OrgID != st.Members[j].OrgID {
76				return st.Members[i].OrgID < st.Members[j].OrgID
77			}
78			return st.Members[i].UserID < st.Members[j].UserID
79		})
80		sort.Slice(st.APIKeys, func(i, j int) bool { return st.APIKeys[i].ID < st.APIKeys[j].ID })
81		sort.Slice(st.Invites, func(i, j int) bool { return st.Invites[i].ID < st.Invites[j].ID })
82		sort.Slice(st.Customers, func(i, j int) bool { return st.Customers[i].ID < st.Customers[j].ID })
83		sort.Slice(st.Plans, func(i, j int) bool { return st.Plans[i].ID < st.Plans[j].ID })
84		sort.Slice(st.Subscriptions, func(i, j int) bool { return st.Subscriptions[i].ID < st.Subscriptions[j].ID })
85		sort.Slice(st.Usage, func(i, j int) bool { return st.Usage[i].ID < st.Usage[j].ID })
86		sort.Slice(st.Invoices, func(i, j int) bool { return st.Invoices[i].ID < st.Invoices[j].ID })
87		sort.Slice(st.Payments, func(i, j int) bool { return st.Payments[i].ID < st.Payments[j].ID })
88		sort.Slice(st.WebhookEndpoints, func(i, j int) bool { return st.WebhookEndpoints[i].ID < st.WebhookEndpoints[j].ID })
89		sort.Slice(st.Events, func(i, j int) bool { return st.Events[i].ID < st.Events[j].ID })
90		sort.Slice(st.Deliveries, func(i, j int) bool { return st.Deliveries[i].ID < st.Deliveries[j].ID })
91		return st
92	}
93	
94	// FromState builds a store holding st.
95	func FromState(st State) (*Store, error) {
96		s := New()
97		s.seq = st.Seq
98		dup := func(kind, id string, seen map[string]bool) error {
99			if id == "" || seen[id] {
100				return fmt.Errorf("%w: %s %q is missing or repeated", ErrInvalid, kind, id)
101			}
102			seen[id] = true
103			return nil
104		}
105		seen := map[string]bool{}
106		for _, o := range st.Orgs {
107			if err := dup("organization", o.ID, seen); err != nil {
108				return nil, err
109			}
110			s.orgs[o.ID] = o
111		}
112		for _, u := range st.Users {
113			if err := dup("user", u.ID, seen); err != nil {
114				return nil, err
115			}
116			s.users[u.ID] = u
117			s.usersByEmail[normEmail(u.Email)] = u.ID
118		}
119		for _, m := range st.Members {
120			if _, ok := s.orgs[m.OrgID]; !ok {
121				return nil, fmt.Errorf("%w: member of unknown organization %q", ErrInvalid, m.OrgID)
122			}
123			if _, ok := s.users[m.UserID]; !ok {
124				return nil, fmt.Errorf("%w: member is unknown user %q", ErrInvalid, m.UserID)
125			}
126			s.members[memberKey{m.OrgID, m.UserID}] = m
127		}
128		for _, k := range st.APIKeys {
129			if err := dup("API key", k.ID, seen); err != nil {
130				return nil, err
131			}
132			s.apiKeys[k.ID] = k
133			if k.Token != "" {
134				s.keysByToken[k.Token] = k.ID
135			}
136		}
137		for _, i := range st.Invites {
138			if err := dup("invite", i.ID, seen); err != nil {
139				return nil, err
140			}
141			s.invites[i.ID] = i
142		}
143		for _, c := range st.Customers {
144			if err := dup("customer", c.ID, seen); err != nil {
145				return nil, err
146			}
147			s.customers[c.ID] = copyCustomer(c)
148			s.customersByEmail[normEmail(c.Email)] = c.ID
149		}
150		for _, p := range st.Plans {
151			if err := dup("plan", p.ID, seen); err != nil {
152				return nil, err
153			}
154			s.plans[p.ID] = p
155		}
156		for _, sub := range st.Subscriptions {
157			if err := dup("subscription", sub.ID, seen); err != nil {
158				return nil, err
159			}
160			s.subs[sub.ID] = copySub(sub)
161		}
162		s.usage = append(s.usage, st.Usage...)
163		for _, inv := range st.Invoices {
164			if err := dup("invoice", inv.ID, seen); err != nil {
165				return nil, err
166			}
167			s.invoices[inv.ID] = copyInvoice(inv)
168		}
169		for _, p := range st.Payments {
170			if err := dup("payment", p.ID, seen); err != nil {
171				return nil, err
172			}
173			s.payments[p.ID] = p
174		}
175		for _, ep := range st.WebhookEndpoints {
176			if err := dup("webhook endpoint", ep.ID, seen); err != nil {
177				return nil, err
178			}
179			s.endpoints[ep.ID] = copyEndpoint(ep)
180		}
181		for _, e := range st.Events {
182			if err := dup("event", e.ID, seen); err != nil {
183				return nil, err
184			}
185			s.events[e.ID] = e
186		}
187		for _, d := range st.Deliveries {
188			if err := dup("delivery", d.ID, seen); err != nil {
189				return nil, err
190			}
191			s.delivs[d.ID] = copyDelivery(d)
192		}
193		return s, nil
194	}
