15	func TestSaveAndLoad(t *testing.T) {
16		now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
17		st := store.New()
18		o, _ := st.CreateOrg("A", store.OrgTeam, "Europe/Berlin", 1900, now)
19		u, _ := st.CreateUser("ann@example.com", "Ann", now)
20		_, _ = st.AddMember(o.ID, u.ID, store.RoleOwner, now)
21		k, _ := st.CreateAPIKey(o.ID, u.ID, "k", now)
22		c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
23		_, _ = st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.EUR, Lines: []store.Line{{Description: "x", Quantity: 2, UnitAmount: 150}}}, now)
24	
25		path := filepath.Join(t.TempDir(), "tally.json")
26		if err := Save(st, path, now); err != nil {
27			t.Fatal(err)
28		}
29		got, err := Load(path)
30		if err != nil {
31			t.Fatal(err)
32		}
33		if !reflect.DeepEqual(got.Export(), st.Export()) {
34			t.Fatal("the loaded store differs from the saved one")
35		}
36		if _, ok := got.APIKeyByToken(k.Token); !ok {
37			t.Fatal("API keys do not work after a reload")
38		}
39	}
