170	func TestSubscriptionsAndInvoices(t *testing.T) {
171		e := apitest.New(t)
172		c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
173		p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
174		var sub store.Subscription
175		e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID, "quantity": 2}, &sub)
176		if sub.Status != store.Active || sub.Quantity != 2 {
177			t.Fatalf("subscription = %+v", sub)
178		}
179		type invoice struct {
180			store.Invoice
181			Subtotal, Discount, Tax, Total int64
182			TotalFormatted                 string `json:"total_formatted"`
183			Description                    string `json:"description"`
184			Customer                       *struct{ ID, Name, Email string }
185		}
186		var invs struct{ Items []invoice }
187		e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+c.ID, e.Acme.Key, nil, &invs)
188		if len(invs.Items) != 1 || invs.Items[0].Total != 4000 || invs.Items[0].Status != store.InvoiceOpen || invs.Items[0].Customer == nil || invs.Items[0].Customer.Name != "Jane" {
189			t.Fatalf("invoices = %+v", invs)
190		}
191		first := invs.Items[0]
192		if !strings.HasPrefix(first.Description, "Team, ") || first.TotalFormatted != "$40.00" {
193			t.Fatalf("invoice view = %+v", first)
194		}
195	
196		var paid struct {
197			Invoice invoice       `json:"invoice"`
198			Payment store.Payment `json:"payment"`
199		}
200		if r := e.Do("POST", "/v1/invoices/"+first.ID+"/pay", e.Acme.Key, nil); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "no_payment_method" {
201			t.Fatalf("pay without a method: %s", r)
202		}
203		r := e.Do("POST", "/v1/invoices/"+first.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_declined"})
204		if m := r.Map(t); r.Code != http.StatusPaymentRequired || m["error"] != "payment_declined" || m["decline_code"] != "card_declined" {
205			t.Fatalf("declined: %s", r)
206		}
207		if r := e.Do("POST", "/v1/invoices/"+first.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_gateway_down"}); r.Code != http.StatusServiceUnavailable {
208			t.Fatalf("gateway down: %s", r)
209		}
210		e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+first.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"}, &paid)
211		if paid.Invoice.Status != store.InvoicePaid || paid.Payment.Amount != 4000 || paid.Payment.Status != store.PaymentSucceeded {
212			t.Fatalf("paid = %+v", paid)
213		}
214		if r := e.Do("POST", "/v1/invoices/"+first.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "already_paid" {
215			t.Fatalf("pay twice: %s", r)
216		}
217		if r := e.Do("POST", "/v1/invoices/"+first.ID+"/void", e.Acme.Key, nil); r.Code != http.StatusConflict {
218			t.Fatalf("void a paid invoice: %s", r)
219		}

