35	func TestPaySucceeds(t *testing.T) {
36		s, gw, pub, inv := setup(t, store.Line{Description: "x", Quantity: 2, UnitAmount: 500})
37		paid, p, err := s.Pay(context.Background(), inv.OrgID, inv.ID, "pm_card_visa")
38		if err != nil {
39			t.Fatal(err)
40		}
41		if paid.Status != store.InvoicePaid || paid.PaidAt == nil {
42			t.Fatalf("invoice = %+v", paid)
43		}
44		if p.Status != store.PaymentSucceeded || p.Amount != 1100 || p.GatewayRef == "" { // 1000 + 10% tax
45			t.Fatalf("payment = %+v", p)
46		}
47		if cs := gw.Charges(); len(cs) != 1 || cs[0].Amount != 1100 || cs[0].Currency != money.USD {
48			t.Fatalf("charges = %+v", cs)
49		}
50		if len(pub.types) != 1 || pub.types[0] != "invoice.paid" {
51			t.Fatalf("events = %v", pub.types)
52		}
53		if _, _, err := s.Pay(context.Background(), inv.OrgID, inv.ID, "pm_card_visa"); !errors.Is(err, ErrAlreadyPaid) {
54			t.Fatalf("second pay: %v", err)
55		}
56	}
