69			t.Fatalf("invoice = %+v", got)
70		}
71		if len(gw.Charges()) != 0 || len(gw.Calls()) != 1 {
72			t.Fatalf("calls %d, charges %d", len(gw.Calls()), len(gw.Charges()))
73		}
74		if len(pub.types) != 1 || pub.types[0] != "invoice.payment_failed" {
75			t.Fatalf("events = %v", pub.types)
76		}
77	}
