92			t.Fatalf("err = %v", err)
93		}
94		if _, err := s.Store.UpdateCustomer(inv.OrgID, inv.CustomerID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil }); err != nil {
95			t.Fatal(err)
96		}
97		if paid, _, err := s.Pay(context.Background(), inv.OrgID, inv.ID, ""); err != nil || paid.Status != store.InvoicePaid {
98			t.Fatalf("pay with the default method: %+v, %v", paid, err)
99		}
100	}
