package api

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"net/http"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
)

// idempotencyTTL is how long an answer kept for an Idempotency-Key is replayed.
const idempotencyTTL = 24 * time.Hour

// busyKey is an Idempotency-Key of an organization whose request is being handled.
type busyKey struct{ org, key string }

// validIdempotencyKey reports whether key is 1 to 255 printable ASCII characters (a space counts as printable).
func validIdempotencyKey(key string) bool {
	if key == "" || len(key) > 255 {
		return false
	}
	for i := 0; i < len(key); i++ {
		if key[i] < 0x20 || key[i] > 0x7e {
			return false
		}
	}
	return true
}

// payWithKey is payOnce for a request with an Idempotency-Key. The first request with a key is handled and its answer is
// kept, unless it is a 5xx: a retry then tries again. A later request with the same key, invoice and body gets the kept
// answer back with Idempotent-Replayed: true. The same key with another invoice or body is refused, and a request that
// finds the key still being handled is refused at once.
func (s *Server) payWithKey(w http.ResponseWriter, r *http.Request, p auth.Principal, key string, body []byte) {
	now := s.clock.Now()
	invoiceID := r.PathValue("id")
	sum := sha256.Sum256(body)
	bodyHash := hex.EncodeToString(sum[:])

	s.idemMu.Lock()
	rec, found := s.store.IdempotencyRecord(p.OrgID, key)
	if found && now.Before(rec.CreatedAt.Add(idempotencyTTL)) {
		s.idemMu.Unlock()
		if rec.InvoiceID != invoiceID || rec.BodyHash != bodyHash {
			writeError(w, http.StatusUnprocessableEntity, "idempotency_key_reused", "this Idempotency-Key was used for another invoice or request body")
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Idempotent-Replayed", "true")
		w.WriteHeader(rec.Status)
		_, _ = w.Write(rec.Body)
		return
	}
	k := busyKey{p.OrgID, key}
	if s.idemBusy[k] {
		s.idemMu.Unlock()
		writeError(w, http.StatusConflict, "request_in_progress", "a request with this Idempotency-Key is still being handled")
		return
	}
	s.idemBusy[k] = true
	s.idemMu.Unlock()
	// The key is released after the answer is kept, so a request that arrives next finds the answer, not an empty key.
	defer func() {
		s.idemMu.Lock()
		defer s.idemMu.Unlock()
		delete(s.idemBusy, k)
	}()

	rc := newRecorder()
	s.payOnce(rc, r, p)
	if rc.status < http.StatusInternalServerError {
		s.store.SaveIdempotencyRecord(store.IdempotencyRecord{OrgID: p.OrgID, Key: key, InvoiceID: invoiceID, BodyHash: bodyHash,
			Status: rc.status, Body: rc.body.Bytes(), CreatedAt: now})
	}
	for name, vs := range rc.header {
		w.Header()[name] = vs
	}
	w.WriteHeader(rc.status)
	_, _ = w.Write(rc.body.Bytes())
}

// recorder is the response writer a keyed request is answered into, so that the answer can be kept as well as sent.
type recorder struct {
	header http.Header
	status int
	body   bytes.Buffer
}

func newRecorder() *recorder { return &recorder{header: http.Header{}, status: http.StatusOK} }

func (rc *recorder) Header() http.Header { return rc.header }

func (rc *recorder) WriteHeader(status int) { rc.status = status }

func (rc *recorder) Write(b []byte) (int, error) { return rc.body.Write(b) }

