package api_test

import (
	"net/http"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// openInvoice creates an open invoice of 10.00 for a new customer of org.
func openInvoice(e *apitest.Env, org apitest.Org, email string) store.Invoice {
	e.T.Helper()
	c := e.CreateCustomer(org, "Jane", email)
	var inv store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", org.Key, map[string]any{"customer_id": c.ID, "currency": "USD",
		"lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 1000}}}, &inv)
	return inv
}

// payWithKey pays an invoice of org with payment method pm and the Idempotency-Key key.
func payWithKey(e *apitest.Env, org apitest.Org, invoiceID, key, pm string) *apitest.Response {
	e.T.Helper()
	return e.DoWith("POST", "/v1/invoices/"+invoiceID+"/pay", org.Key, map[string]string{"payment_method": pm},
		http.Header{"Idempotency-Key": {key}})
}

func TestPayIdempotencyKeyFormat(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(e, e.Acme, "jane@example.com")
	for _, key := range []string{"", strings.Repeat("k", 256), "tab\tkey", "café", "del\x7f"} {
		r := payWithKey(e, e.Acme, inv.ID, key, "pm_card_visa")
		if r.Code != http.StatusBadRequest || r.Map(t)["error"] != "invalid_idempotency_key" {
			t.Fatalf("key %q: %s", key, r)
		}
	}
	two := e.DoWith("POST", "/v1/invoices/"+inv.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"},
		http.Header{"Idempotency-Key": {"a", "b"}})
	if two.Code != http.StatusBadRequest || two.Map(t)["error"] != "invalid_idempotency_key" {
		t.Fatalf("two keys: %s", two)
	}
	// Valid keys get past the check; a declined card keeps the invoice open for the next case.
	for _, key := range []string{"k", "order 42 (retry #1)", strings.Repeat("k", 255)} {
		if r := payWithKey(e, e.Acme, inv.ID, key, "pm_card_declined"); r.Code != http.StatusPaymentRequired {
			t.Fatalf("key %q: %s", key, r)
		}
	}
	if n := len(e.Gateway.Calls()); n != 3 {
		t.Fatalf("gateway calls = %d, want 3", n)
	}
}

func TestPayReplaysTheFirstAnswer(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(e, e.Acme, "jane@example.com")
	first := payWithKey(e, e.Acme, inv.ID, "order-1", "pm_card_visa")
	if first.Code != http.StatusOK || first.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("first: %s", first)
	}
	retry := payWithKey(e, e.Acme, inv.ID, "order-1", "pm_card_visa")
	if retry.Code != first.Code || retry.Header.Get("Idempotent-Replayed") != "true" || string(retry.Body) != string(first.Body) {
		t.Fatalf("retry = %s (replayed %q), first = %s", retry, retry.Header.Get("Idempotent-Replayed"), first)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("charges = %d, want 1", n)
	}
}

func TestPayKeyReusedForAnotherInvoiceOrBody(t *testing.T) {
	e := apitest.New(t)
	inv1 := openInvoice(e, e.Acme, "a@example.com")
	inv2 := openInvoice(e, e.Acme, "b@example.com")
	if r := payWithKey(e, e.Acme, inv1.ID, "k", "pm_card_visa"); r.Code != http.StatusOK {
		t.Fatalf("first: %s", r)
	}
	if r := payWithKey(e, e.Acme, inv2.ID, "k", "pm_card_visa"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "idempotency_key_reused" {
		t.Fatalf("another invoice: %s", r)
	}
	if r := payWithKey(e, e.Acme, inv1.ID, "k", "pm_card_declined"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "idempotency_key_reused" {
		t.Fatalf("another body: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("charges = %d, want 1", n)
	}
}

func TestPayKeysBelongToAnOrganization(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(e, e.Acme, "a@example.com")
	ginv := openInvoice(e, e.Globex, "b@example.com")
	if r := payWithKey(e, e.Acme, inv.ID, "same", "pm_card_visa"); r.Code != http.StatusOK {
		t.Fatalf("acme: %s", r)
	}
	r := payWithKey(e, e.Globex, ginv.ID, "same", "pm_card_visa")
	if r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("globex with the same key: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 2 {
		t.Fatalf("charges = %d, want 2", n)
	}
}

func TestPayRequestInProgress(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(e, e.Acme, "jane@example.com")
	started, release := make(chan struct{}), make(chan struct{})
	e.Gateway.OnCharge = func(payments.ChargeRequest) {
		started <- struct{}{}
		<-release
	}
	done := make(chan *apitest.Response, 1)
	go func() { done <- payWithKey(e, e.Acme, inv.ID, "k", "pm_card_visa") }()
	<-started

	// The same key is refused at once, and so is another key for the same invoice: the charge is under way.
	if r := payWithKey(e, e.Acme, inv.ID, "k", "pm_card_visa"); r.Code != http.StatusConflict || r.Map(t)["error"] != "request_in_progress" {
		t.Fatalf("same key while in progress: %s", r)
	}
	if r := payWithKey(e, e.Acme, inv.ID, "other", "pm_card_visa"); r.Code != http.StatusConflict || r.Map(t)["error"] != "payment_in_progress" {
		t.Fatalf("other key while in progress: %s", r)
	}
	close(release)
	first := <-done
	if first.Code != http.StatusOK {
		t.Fatalf("first: %s", first)
	}
	if r := payWithKey(e, e.Acme, inv.ID, "k", "pm_card_visa"); r.Code != http.StatusOK || r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("after the first finished: %s", r)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("charges = %d, want 1", n)
	}
}

func TestPayServerErrorsAreNotKept(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(e, e.Acme, "jane@example.com")
	for range 2 {
		r := payWithKey(e, e.Acme, inv.ID, "k", "pm_gateway_down")
		if r.Code != http.StatusServiceUnavailable || r.Map(t)["error"] != "gateway_unavailable" || r.Header.Get("Idempotent-Replayed") != "" {
			t.Fatalf("gateway down: %s", r)
		}
	}
	if n := len(e.Gateway.Calls()); n != 2 {
		t.Fatalf("the retry did not try the payment again: %d gateway calls", n)
	}
}

func TestPayOtherAnswersAreKept(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(e, e.Acme, "jane@example.com")
	first := payWithKey(e, e.Acme, inv.ID, "k", "pm_card_declined")
	if first.Code != http.StatusPaymentRequired {
		t.Fatalf("first: %s", first)
	}
	retry := payWithKey(e, e.Acme, inv.ID, "k", "pm_card_declined")
	if retry.Code != http.StatusPaymentRequired || retry.Header.Get("Idempotent-Replayed") != "true" || string(retry.Body) != string(first.Body) {
		t.Fatalf("retry = %s, first = %s", retry, first)
	}
	if n := len(e.Gateway.Calls()); n != 1 {
		t.Fatalf("gateway calls = %d, want 1", n)
	}
}

func TestPayKeyExpiresAfter24Hours(t *testing.T) {
	e := apitest.New(t)
	inv := openInvoice(e, e.Acme, "jane@example.com")
	payWithKey(e, e.Acme, inv.ID, "k", "pm_card_declined")

	e.Clock.Advance(24*time.Hour - time.Minute)
	if r := payWithKey(e, e.Acme, inv.ID, "k", "pm_card_declined"); r.Header.Get("Idempotent-Replayed") != "true" {
		t.Fatalf("23h59m later: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 1 {
		t.Fatalf("a replay charged again: %d gateway calls", n)
	}

	e.Clock.Advance(time.Minute)
	if r := payWithKey(e, e.Acme, inv.ID, "k", "pm_card_declined"); r.Code != http.StatusPaymentRequired || r.Header.Get("Idempotent-Replayed") != "" {
		t.Fatalf("24h later the key is new: %s", r)
	}
	if n := len(e.Gateway.Calls()); n != 2 {
		t.Fatalf("gateway calls = %d, want 2", n)
	}
}

