package store

import (
	"testing"
	"time"
)

func TestIdempotencyRecordsAreScopedAndSurviveExport(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := New()
	rec := IdempotencyRecord{OrgID: "org_1", Key: "k", InvoiceID: "in_1", BodyHash: "h", Status: 402, Body: []byte(`{"error":"x"}`), CreatedAt: now}
	st.SaveIdempotencyRecord(rec)
	if _, ok := st.IdempotencyRecord("org_2", "k"); ok {
		t.Fatal("a key of one organization was found in another")
	}
	if got, ok := st.IdempotencyRecord("org_1", "k"); !ok || got.Status != 402 || string(got.Body) != `{"error":"x"}` {
		t.Fatalf("record = %+v, %v", got, ok)
	}

	loaded, err := FromState(st.Export())
	if err != nil {
		t.Fatal(err)
	}
	if got, ok := loaded.IdempotencyRecord("org_1", "k"); !ok || got.InvoiceID != "in_1" || !got.CreatedAt.Equal(now) {
		t.Fatalf("after a reload: %+v, %v", got, ok)
	}

	rec.Status = 200
	st.SaveIdempotencyRecord(rec)
	if got, _ := st.IdempotencyRecord("org_1", "k"); got.Status != 200 {
		t.Fatalf("a saved record replaces the earlier one: status %d", got.Status)
	}
}

